        private static long MeasureQueries(StableIdentityBenchScene scene, SpatialRequest request, int mode, int operations,
            AllocationMeter meter, out AllocationSample allocation)
        {
            AllocationSample before = meter.Read();
            long start = Stopwatch.GetTimestamp();
            for (int operation = 0; operation < operations; operation++)
                scene.Execute(request,mode);
            long elapsed = Stopwatch.GetTimestamp()-start;
            allocation = meter.Difference(before);
            return elapsed;
        }

        private static int QueryBatch(StableIdentityBenchScene legacy, StableIdentityBenchScene stable,
            SpatialRequest request, int mode, AllocationMeter meter)
        {
            // Calibrate outside samples. A common batch keeps the faster side above timer noise,
            // without making a slower runtime execute tens of milliseconds for each Any sample.
            int operations = mode == 0 ? 4096 : 4;
            long oldTime = MeasureQueries(legacy,request,mode,operations,meter,out _);
            long newTime = MeasureQueries(stable,request,mode,operations,meter,out _);
            long elapsed = Math.Max(1,Math.Min(oldTime,newTime));
            long target = Math.Max(1,Stopwatch.Frequency/500);
            while (elapsed < target && operations < 131072)
            {
                elapsed *= 2;
                operations *= 2;
            }
            while (elapsed >= target*2 && operations > 1)
            {
                elapsed /= 2;
                operations /= 2;
            }
            return operations;
        }

        public static double QueryIncrease(long legacyTicks, long stableTicks)
        {
            if (legacyTicks <= 0 || stableTicks <= 0)
                throw new InvalidOperationException("Both query timings must be positive.");
            return 100.0*(stableTicks-legacyTicks)/legacyTicks;
        }

        public static bool WithinQueryBudget(double increase) => !double.IsNaN(increase) && !double.IsInfinity(increase) && increase <= 5;

        private static void CheckQueryBudgetControl(TextWriter output)
        {
            if (!WithinQueryBudget(QueryIncrease(1000,1000)) || WithinQueryBudget(QueryIncrease(1000,1060)))
                throw new InvalidOperationException("Query budget positive control failed.");
            bool detected = false;
            try { CheckKey(1,2); }
            catch (InvalidOperationException) { detected = true; }
            if (!detected)
                throw new InvalidOperationException("Query signature positive control failed.");
            output.WriteLine("query-controls|injected-6pct=detected; injected-signature=detected");
        }

        private static ulong QueryWorkload(StableIdentityBenchScene scene)
        {
            var hash = new StateHash();
            foreach (SpatialBody body in scene.Bodies)
            {
                body.Entity.WriteState(hash);
                body.Position.WriteState(hash);
                body.Collider.WriteState(hash);
            }
            return hash.Value;
        }

        private static ulong QueryOutput(StableIdentityBenchScene scene, SpatialHit[] expected, int mode)
        {
            var hash = new StateHash();
            hash.Add(expected.Length);
            int count = mode == 0 ? 0 : mode == 1 ? Math.Min(1,expected.Length) : mode == 2 ? Math.Min(512,expected.Length) : expected.Length;
            hash.Add(count);
            for (int i = 0; i < count; i++)
            {
                hash.Add(scene.Keys[expected[i].Entity.Id]);
                hash.Add(expected[i].Distance.Raw);
            }
            return hash.Value;
        }
